// src/components/TweetCard.tsx
import React from 'react';
import { deleteTweet } from '../api/tweets';

interface Tweet {
  id: number;
  tweet_id: string;
  author_name: string;
  profile_pic: string | null;
  content: string;
  likes: number;
  comments: number;
  order: number;
  profileLink?: string; // Optional, based on your data
}

interface TweetCardProps {
  tweet: Tweet;
  wallId: number;
  onDelete: (tweetId: number) => void;

}

const TweetCard = ({ tweet, wallId, onDelete, onClick }) => {
  const handleDelete = async () => {
    try {
      await deleteTweet(wallId, tweet.id);
      onDelete(tweet.id);
    } catch (err) {
      console.error('Failed to delete tweet:', err);
    }
  };

  return (
    <div className="bg-white p-4 rounded-lg shadow-md hover:shadow-lg transition w-full max-w-md mx-auto border border-gray-200">
      {/* Flex container for profile pic and text */}
      <div className="flex items-center mb-2">
        <img
          src={tweet.profile_pic || '/placeholder.jpg'}
          alt={tweet.author_name}
          className="w-10 h-10 rounded-full mr-3 object-cover"
        />
        <div className="flex-1">
          <p className="font-semibold text-gray-800">{tweet.author_name}</p>
          {tweet.profileLink && (
            <a
              href={tweet.profileLink}
              target="_blank"
              rel="noopener noreferrer"
              className="text-blue-500 text-sm hover:underline"
              onClick={onClick}
            >
              @{tweet.author_name}
            </a>
          )}
        </div>
      </div>
      {/* Truncated content */}
      <p className="text-gray-700 mb-2 line-clamp-3 break-words">
        {tweet.content}
      </p>
      {/* Stats and delete button */}
      <div className="flex justify-between items-center text-gray-500 text-sm">
        <span className="flex space-x-2">
          <span>❤️ {tweet.likes}</span>
          <span>💬 {tweet.comments}</span>
        </span>
        <button
          onClick={handleDelete}
          className="text-red-500 hover:text-red-700 font-semibold"
        >
          Delete
        </button>
      </div>
    </div>
  );
};

export default TweetCard;
